<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class EventPerformance extends Model{protected $fillable=['event_id','student_id','teacher_id','program_number','student_name','student_class','title','composer','instrument','accompanist','description','is_published'];protected $casts=['is_published'=>'boolean'];public function student(){return $this->belongsTo(Student::class);}public function event(){return $this->belongsTo(Event::class);}public function teacher(){return $this->belongsTo(Teacher::class);}public function media(){return $this->belongsToMany(Media::class,'event_performance_media')->withPivot('sort')->orderByPivot('sort');}}